export type Item = {
  type: string;
};

export type Step = {
  op: string;
  items: Item[];
};

export type Customer = {
  yearsWithMHPCO: number;
};

export type Scenario = {
  customer: Customer;
  steps: Step[];
};

export type QuoteResult = {
  premium: number;
};

export type ScenarioOutcome = {
  results: QuoteResult[];
};

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const FIRST_INSURANCE_PERCENT = 10;

// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
// Math.ceil turns the drift into a whole extra gold piece. The spec requires
// intermediates to stay exact, so every percentage goes through here.
const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

// Rounding always favours MHPCO: premiums round up, payouts round down.
const roundPremium = (amount: number): number => Math.ceil(amount);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const quoteStep = (step: Step): QuoteResult => {
  const basePremium = step.items.reduce(
    (sum, item) => sum + basePremiumOf(item),
    0,
  );
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);

  return {
    premium: roundPremium(
      basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
    ),
  };
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map(quoteStep),
});

