export type Item = {
  type: string;
};

export type Step = {
  op: string;
  items: Item[];
};

export type Customer = {
  yearsWithMHPCO: number;
};

export type Scenario = {
  customer: Customer;
  steps: Step[];
};

export type QuoteResult = {
  premium: number;
};

export type ScenarioOutcome = {
  results: QuoteResult[];
};

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_PERCENT = 10;

// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
// Math.ceil turns the drift into a whole extra gold piece. The spec requires
// intermediates to stay exact, so every percentage goes through here.
const PERCENT_WHOLE = 100;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / PERCENT_WHOLE;

// Rounding always favours MHPCO: premiums round up, payouts round down.
const roundPremium = (amount: number): number => Math.ceil(amount);

const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

// Exactly 3 alike items are priced as a single block, otherwise each item is
// priced on its own. NOTE: the spec restricts blocks to components (rune,
// moonstone), so 3 swords should *not* block-price. No test demands that yet,
// so the restriction is not implemented — this is where it belongs.
const groupBasePremiumOf = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);

// The policy base premium is the sum of the base premiums of each group of
// alike items.
const policyBasePremiumOf = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + groupBasePremiumOf(type, count),
    0,
  );

const quoteStep = (step: Step): QuoteResult => {
  const basePremium = policyBasePremiumOf(step.items);
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);

  return {
    premium: roundPremium(
      basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
    ),
  };
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map(quoteStep),
});

