import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums per item type ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
  });
  it("single sword → base premium 100 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    };

    // 100 G base + 10 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("single amulet → base premium 60 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    };

    // 60 G base + 6 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("single staff → base premium 80 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    };

    // 80 G base + 8 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
  });
  it("single potion → base premium 40 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    };

    // 40 G base + 4 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
  });
  it("single rune → base premium 25 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    };

    // 25 G base + 2.5 G first insurance + 5 G fee = 32.5 → rounded up
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 33 }] });
  });
  it("single moonstone → base premium 25 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
    };

    // 25 G base + 2.5 G first insurance + 5 G fee = 32.5 → rounded up
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 33 }] });
  });

  // --- Building block of 3 alike components ---
  it("2 runes → 50 G base premium", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    };

    // 50 G base + 5 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → 60 G base premium (block applies)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    };

    // 60 G block base + 6 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
          ],
        },
      ],
    };

    // 100 G base + 10 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → 175 G base premium", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
        },
      ],
    };

    // 175 G base + 17.5 G first insurance + 5 G fee = 197.5 → rounded up
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    };

    // 75 G base + 7.5 G first insurance + 5 G fee = 87.5 → rounded up
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 swords → 300 G base premium (blocks apply to components only)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 3 }, () => ({ type: "sword" })),
        },
      ],
    };

    // 300 G base + 30 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 335 }] });
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            ...Array.from({ length: 3 }, () => ({ type: "rune" })),
            ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
          ],
        },
      ],
    };

    // 120 G base (two blocks) + 12 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-specific modifiers ---
  it("cursed sword adds a 50 % surcharge on that item's base premium", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: true },
          ],
        },
      ],
    };

    // 100 G base + 50 G curse + 10 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 165 }] });
  });
  it("sword with enchantment 5 adds a 30 % high-enchantment surcharge", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 5, cursed: false },
          ],
        },
      ],
    };

    // 100 G base + 30 G high enchantment + 10 G first insurance + 5 G fee
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 145 }] });
  });
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 gets both surcharges");

  // --- Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the cursed item's base) → 210 G before further modifiers and fee",
  );

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("each item in a quote carries a 10 % first insurance surcharge");
  it.todo("the second quote of a customer receives a 15 % follow-up contract discount");
  it.todo("a 5 G processing fee is added to every premium");

  // --- Rounding ---
  it.todo("premium of 197.5 G is rounded up to 198 G (MHPCO's favour)");
  it.todo("payout of 350.5 G is rounded down to 350 G (MHPCO's favour)");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
  it.todo(
    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
  );

  // --- Claim: standard reimbursement ---
  it.todo("steel sword, enchantment 3, damage 500 G → payout 400 G (damage minus deductible)");
  it.todo("rune (no enchantment, no material), damage 200 G → payout 100 G");

  // --- Claim: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");

  // --- Claim: deductible per damage event ---
  it.todo(
    "dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)",
  );

  // --- Claim: cap ---
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
  it.todo("cursed sword → cap 2000 G based on the unmodified insurance value");
  it.todo("sword policy, first claim of 1500 G → payout 1400 G, remaining cap 600 G");
  it.todo("sword policy, second claim of 1500 G → payout 600 G, remaining cap 0 G");

  // --- Multiple items of the same type ---
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries → each treated as a separate damage with its own deductible");
  it.todo("more damage entries of a type than insured → the claim is rejected with an error");

  // --- Errors ---
  it.todo("quote with an unknown item type (broomstick) → error");
  it.todo("claim for an item not part of the policy → error");
  it.todo("claim with a damage entry of unknown item type → error");
  it.todo("claim with a negative damage amount (-200) → error");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout");
  it.todo("CLI exits with a non-zero status and writes to stderr on an unknown item type, with no results on stdout");
});

