  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

// Rounding always favours MHPCO: payouts round down.
const roundPayout = (amount: number): number => Math.floor(amount);

const insuranceSumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

// A policy is created by a quote step and accumulates claims against its cap.
type Policy = {
  items: Item[];
  remainingCap: number;
};

const claimStep = (step: ClaimStep, policy: Policy): ClaimResult => {
  const desired = step.incident.damages.reduce(
    (total, damage) => total + (damage.amount - DEDUCTIBLE),
    0,
  );
  const payout = roundPayout(desired);

  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
